package com.myadoran.elywatch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(com.myadoran.elywatch.ElyWatchPlugin.CONFIG_GROUP)
public interface ElyWatchConfig extends Config
{
	@ConfigItem(
			position = 1,
			keyName = "chatNotify",
			name = "Chat notifications",
			description = "Show game messages for equipping and un-equipping."
	)
	default boolean chatNotify()
	{
		return true;
	}

	enum apiMethodEquip
	{
		GET,
		POST
	}

	@ConfigItem(
			position = 2,
			keyName = "apiMethodEquip",
			name = "Method Equip",
			description = "HTTP method to be used for API call on equip."
	)
	default apiMethodEquip apiMethodEquip()
	{
		return apiMethodEquip.GET;
	}

	@ConfigItem(
			position = 3,
			keyName = "apiHostEquip",
			name = "API Hostname Equip",
			description = "Hostname that gets called on equip."
	)
	default String apiHostEquip()
	{
		return "";
	}

	enum apiMethodUnEquip
	{
		GET,
		POST
	}

	@ConfigItem(
			position = 4,
			keyName = "apiMethodUnEquip",
			name = "Method UnEquip",
			description = "HTTP method to be used for API call on unequip."
	)
	default apiMethodUnEquip apiMethodUnEquip()
	{
		return apiMethodUnEquip.GET;
	}

	@ConfigItem(
			position = 5,
			keyName = "apiHostUnEquip",
			name = "API Hostname UnEquip",
			description = "Hostname that gets called on unequip."
	)
	default String apiHostUnEquip()
	{
		return "";
	}

	@ConfigItem(
			position = 6,
			keyName = "bearerToken",
			name = "Bearer token",
			description = "API key to be used for the call."
	)
	default String bearerToken()
	{
		return "";
	}

}

package com.myadoran.elywatch;

import java.awt.*;
import java.io.IOException;
import javax.annotation.Nonnull;
import javax.inject.Inject;

import com.google.inject.Provides;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import okhttp3.*;

@PluginDescriptor(
		name = "ElyWatch",
		description = "Handles Ely watching duties",
		tags = {"shield", "ely"},
		enabledByDefault = true
)

public class ElyWatchPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private OkHttpClient httpClient;

	@Provides
	ElyWatchConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ElyWatchConfig.class);
	}

	@Inject
	private ElyWatchConfig config;

	static final String CONFIG_GROUP = "elywatch";

	private boolean isWearingEly;

	@Override
	protected void startUp() throws Exception
	{
		clientThread.invokeLater(() ->
		{
			final ItemContainer container = client.getItemContainer(InventoryID.WORN);

			if (container != null)
			{
				isWearingEly = false;
				checkInventory(container);
			}
		});
	}


	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getItemContainer() != client.getItemContainer(InventoryID.WORN))
		{
			return;
		}

		checkInventory(event.getItemContainer());
	}


	private void checkInventory(ItemContainer equipment)
	{
		try
		{
			final Item shield = equipment.getItem(EquipmentInventorySlot.SHIELD.getSlotIdx());
			if (shield.getId() == 12817)
			{
				if (!isWearingEly)
				{
					isWearingEly = true;
					if (config.chatNotify())
					{
						sendChatMessage(Color.blue, "Ely equipped");
						makeApiCall();
					}
				}
			}
			else
			{
				if (isWearingEly)
				{
					isWearingEly = false;
					if (config.chatNotify())
					{
						sendChatMessage(Color.red, "Ely unequipped");
						makeApiCall();
					}
				}
			}
		}
		catch (Exception e)
		{
			if (isWearingEly)
			{
				isWearingEly = false;
				if (config.chatNotify())
				{
					sendChatMessage(Color.red, "Ely unequipped");
					makeApiCall();
				}
			}
		}


	}
	private void makeApiCall()
	{
		String url = "";
		String method = "";
		try
		{
			if (isWearingEly)
			{
				url = config.apiHostEquip();
				method = String.valueOf(config.apiMethodEquip());
			}
			if (!isWearingEly)
			{
				url = config.apiHostUnEquip();
				method = String.valueOf(config.apiMethodUnEquip());
			}
			RequestBody body = RequestBody.create(null, new byte[0]);
			Request request = new Request.Builder()
					.url(url)
					.header("accept", "application/json")
					.addHeader("Authorization", config.bearerToken())
					.method(method, body)
					.build();
			httpClient.newCall(request).enqueue(new Callback() {
				@Override
				public void onResponse(Call call, Response response) throws IOException {
				}
				@Override
				public void onFailure(Call call, IOException e) {
					sendChatMessage(Color.red, "Network error in ElyWatch.");
				}
			});
		}
		catch (Exception e)
		{
			sendChatMessage(Color.red, "Something has gone wrong in ElyWatch.");
		}
	}

	private void sendChatMessage(Color color, String chatMessage)
	{
		final String message = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append(color, chatMessage)
				.build();

		chatMessageManager.queue(
				QueuedMessage.builder()
						.type(ChatMessageType.CONSOLE)
						.runeLiteFormattedMessage(message)
						.build());
	}


}

package com.myadoran.elywatch;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ElyWatchPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ElyWatchPlugin.class);
		RuneLite.main(args);
	}
}
